INSERT IGNORE INTO `ehr_announcement` (`id`, `announcement_no`, `title`, `summary`, `category`, `content`, `target_type`, `target_org_ids`, `target_org_names`, `pinned`, `status`, `publish_at`, `offline_at`, `publisher_account_id`, `publisher_name`, `read_count`, `target_count`, `remark`, `deleted`, `created_at`, `updated_at`) VALUES (880000000000000001,'NOTICE-20251225-0001','2026年元旦放假通知','2026年1月1日（周四）放假1天，1月2日（周五）正常上班。','HOLIDAY','<h3>放假安排</h3><p>2026年1月1日（周四，元旦）放假1天，1月2日（周五）正常上班。</p><h3>注意事项</h3><ul><li>请各部门于放假前完成本周工作交接，重要事项提前报备。</li><li>节假日期间安排值班的部门，请于12月30日前将值班表提交人力资源中心。</li><li>离开工作城市外出的同事请按管理规定报备，注意出行安全。</li></ul><p>祝大家元旦快乐、新年顺遂！</p>',0,'','',0,1,'2025-12-25 10:00:00',NULL,NULL,'人力资源中心',2,163,'',0,'2025-12-25 10:00:00','2026-11-08 20:57:03');
INSERT IGNORE INTO `ehr_announcement` (`id`, `announcement_no`, `title`, `summary`, `category`, `content`, `target_type`, `target_org_ids`, `target_org_names`, `pinned`, `status`, `publish_at`, `offline_at`, `publisher_account_id`, `publisher_name`, `read_count`, `target_count`, `remark`, `deleted`, `created_at`, `updated_at`) VALUES (880000000000000002,'NOTICE-20260209-0001','2026年春节放假通知','2026年2月16日（除夕）至2月22日放假，共7天，2月23日（周一）返岗。','HOLIDAY','<h3>放假安排</h3><p>2026年2月16日（周一，除夕）至2月22日（周日）放假，共7天，2月23日（周一）正常上班。</p><h3>注意事项</h3><ul><li>请各部门在2月13日前完成节前工作收尾与交接，明确节日期间紧急联系人。</li><li>值班安排请于2月9日前报人力资源中心备案，值班与加班按公司制度执行。</li><li>返乡、出行请关注天气与交通情况，提前购票，合理安排返程时间。</li><li>节后首个工作日请按时返岗，如有特殊情况须提前向直属上级请假。</li></ul><p>祝全体员工新春快乐、阖家幸福！</p>',0,'','',0,1,'2026-02-09 10:00:00',NULL,NULL,'人力资源中心',2,163,'',0,'2026-02-09 10:00:00','2026-11-08 20:57:03');
INSERT IGNORE INTO `ehr_announcement` (`id`, `announcement_no`, `title`, `summary`, `category`, `content`, `target_type`, `target_org_ids`, `target_org_names`, `pinned`, `status`, `publish_at`, `offline_at`, `publisher_account_id`, `publisher_name`, `read_count`, `target_count`, `remark`, `deleted`, `created_at`, `updated_at`) VALUES (880000000000000003,'NOTICE-20260328-0001','2026年清明节放假通知','2026年4月4日（周六）至4月6日（周一）放假，共3天，4月7日（周二）返岗。','HOLIDAY','<h3>放假安排</h3><p>2026年4月4日（周六）至4月6日（周一）放假，共3天，4月7日（周二）正常上班。</p><h3>注意事项</h3><ul><li>清明祭扫请遵守当地防火与文明祭扫规定，注意人身与交通安全。</li><li>需在假期处理紧急事务的部门，请提前安排值班人员并报备人力资源中心。</li></ul>',0,'','',0,1,'2026-03-28 10:00:00',NULL,NULL,'人力资源中心',2,163,'',0,'2026-03-28 10:00:00','2026-11-08 20:57:02');
INSERT IGNORE INTO `ehr_announcement` (`id`, `announcement_no`, `title`, `summary`, `category`, `content`, `target_type`, `target_org_ids`, `target_org_names`, `pinned`, `status`, `publish_at`, `offline_at`, `publisher_account_id`, `publisher_name`, `read_count`, `target_count`, `remark`, `deleted`, `created_at`, `updated_at`) VALUES (880000000000000004,'NOTICE-20260424-0001','2026年劳动节放假通知','2026年5月1日（周五）至5月5日（周二）放假，共5天，5月6日（周三）返岗。','HOLIDAY','<h3>放假安排</h3><p>2026年5月1日（周五）至5月5日（周二）放假，共5天，5月6日（周三）正常上班。</p><h3>注意事项</h3><ul><li>节前请完成在手工作的节点确认，避免影响项目交付。</li><li>假期出行请关注景区人流与天气预警，错峰出行。</li><li>值班与加班按公司加班管理规定执行，需提前审批。</li></ul><p>祝大家劳动节快乐！</p>',0,'','',0,1,'2026-04-24 10:00:00',NULL,NULL,'人力资源中心',2,163,'',0,'2026-04-24 10:00:00','2026-11-08 20:57:01');
