INSERT IGNORE INTO `ehr_announcement` (`id`, `announcement_no`, `title`, `summary`, `category`, `content`, `target_type`, `target_org_ids`, `target_org_names`, `pinned`, `status`, `publish_at`, `offline_at`, `publisher_account_id`, `publisher_name`, `read_count`, `target_count`, `remark`, `deleted`, `created_at`, `updated_at`) VALUES (880000000000000006,'NOTICE-20260918-0001','2026年中秋节放假通知','2026年9月25日（周五）至9月27日（周日）放假，共3天，9月28日（周一）返岗。','HOLIDAY','<h3>放假安排</h3><p>2026年9月25日（周五，中秋节）至9月27日（周日）放假，共3天，9月28日（周一）正常上班。</p><h3>注意事项</h3><ul><li>请各部门提前安排节前工作交接，确保节日期间业务连续性。</li><li>值班人员名单请于9月18日前报人力资源中心备案。</li></ul><p>祝大家中秋团圆、阖家安康！</p>',0,'','',0,1,'2026-09-15 10:00:00',NULL,NULL,'人力资源中心',2,163,'',0,'2026-09-18 10:00:00','2026-11-08 20:57:35');
INSERT IGNORE INTO `ehr_announcement` (`id`, `announcement_no`, `title`, `summary`, `category`, `content`, `target_type`, `target_org_ids`, `target_org_names`, `pinned`, `status`, `publish_at`, `offline_at`, `publisher_account_id`, `publisher_name`, `read_count`, `target_count`, `remark`, `deleted`, `created_at`, `updated_at`) VALUES (880000000000000007,'NOTICE-20260924-0001','2026年国庆节放假通知','2026年10月1日（周四）至10月7日（周三）放假，共7天，10月8日（周四）返岗。','HOLIDAY','<h3>放假安排</h3><p>2026年10月1日（周四）至10月7日（周三）放假，共7天，10月8日（周四）正常上班。</p><h3>注意事项</h3><ul><li>节前请各部门完成季度工作复盘与四季度计划确认。</li><li>假期值班按排班表执行，紧急联系人须保持通讯畅通。</li><li>出行请注意交通安全，错峰返程，避免影响节后正常办公。</li></ul><p>祝大家国庆快乐！</p>',0,'','',0,1,'2026-09-24 10:00:00',NULL,NULL,'人力资源中心',2,163,'',0,'2026-09-24 10:00:00','2026-11-08 20:56:59');
INSERT IGNORE INTO `ehr_announcement` (`id`, `announcement_no`, `title`, `summary`, `category`, `content`, `target_type`, `target_org_ids`, `target_org_names`, `pinned`, `status`, `publish_at`, `offline_at`, `publisher_account_id`, `publisher_name`, `read_count`, `target_count`, `remark`, `deleted`, `created_at`, `updated_at`) VALUES (880000000019113217,'NOTICE-20260830-3217','关于李明任人力资源中心负责人的通知','任命李明为人力资源中心负责人，自 2026年08月30日 起生效。','APPOINTMENT','<h3>任命决定</h3><p>经集团研究决定，任命李明为人力资源中心负责人，自 2026年08月30日 起生效，任期三年。</p><h3>工作职责</h3><ul><li>全面负责人力资源中心的经营管理、团队建设与业务目标达成。</li><li>严格落实集团各项管理制度，重大事项按流程报批。</li><li>做好关键岗位交接与人才梯队建设，确保各项工作平稳过渡。</li></ul><p>请各相关单位知悉并配合工作。</p><p>特此通知。</p>',0,'','',0,1,'2026-08-30 14:20:00',NULL,NULL,'人力资源中心',0,163,'seed:appointment',0,'2026-08-30 14:20:00','2026-08-30 14:20:00');
